export function getTranslationKeys(languageCode: string): string {
  switch (languageCode) {
    case 'en':
      return getENTranslationData().keys
    case 'de':
      return getDETranslationData().keys
    case 'fr':
      return getFRTranslationData().keys
    case 'se':
      return getSETranslationData().keys
    case 'no':
      return getNOTranslationData().keys
    case 'ar':
      return getARTranslationData().keys
    case 'cn':
      return getCNTranslationData().keys
    case 'ru':
      return getRUTranslationData().keys
    case 'jp':
      return getJPTranslationData().keys
    case 'es':
      return getESTranslationData().keys
    case 'nl':
      return getNLTranslationData().keys
    default:
      return ''
  }
}

export function getTranslationFlag(languageCode: string): string {
  switch (languageCode) {
    case 'en':
      return getENTranslationData().flag
    case 'de':
      return getDETranslationData().flag
    case 'fr':
      return getFRTranslationData().flag
    case 'se':
      return getSETranslationData().flag
    case 'no':
      return getNOTranslationData().flag
    case 'ar':
      return getARTranslationData().flag
    case 'cn':
      return getCNTranslationData().flag
    case 'ru':
      return getRUTranslationData().flag
    case 'jp':
      return getJPTranslationData().flag
    case 'es':
      return getESTranslationData().flag
    case 'nl':
      return getNLTranslationData().flag
    default:
      return ''
  }
}
